def reverse(a):
     i, j = 0, len(a) - 1
     while i < j:
          a[i], a[j] = a[j], a[i]
          i += 1; j -= 1
     return a

def second_largest(a):
     first = second = float('-inf')
     for x in a:
          if x > first:
                first, second = x, first
          elif first > x > second:
                second = x
     return second if second != float('-inf') else None

def rotate(a, k):
     n = len(a); k %= n
     def rev(i, j):
          while i < j:
                a[i], a[j] = a[j], a[i]; i += 1; j -= 1
     rev(0, n - 1); rev(0, k - 1); rev(k, n - 1)
     return a

