def middle(head):
     slow = fast = head
     while fast and fast.next:
         slow = slow.next; fast = fast.next.next
     return slow          # for even length, returns the second middle

def has_cycle(head):
     slow = fast = head
     while fast and fast.next:
         slow, fast = slow.next, fast.next.next
         if slow is fast: return True
     return False

