def balanced(s):
     pairs = {')': '(', ']': '[', '}': '{'}
     st = []
     for ch in s:
          if ch in '([{': st.append(ch)
          elif ch in pairs:
               if not st or st.pop() != pairs[ch]: return False
     return not st

def eval_postfix(expr):
     st = []
     for tok in expr.split():
          if tok in "+-*/":
               b, a = st.pop(), st.pop()              # right operand popped first
               if tok == '+': st.append(a + b)
               elif tok == '-': st.append(a - b)
               elif tok == '*': st.append(a * b)
               else: st.append(int(a / b))            # truncate toward zero
          else:

              st.append(int(tok))
    return st[0]

def to_postfix(s):
    prec = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    out, st = [], []
    for ch in s:
        if ch.isalnum(): out.append(ch)
        elif ch == '(': st.append(ch)
        elif ch == ')':
              while st and st[-1] != '(': out.append(st.pop())
              st.pop()
        else:
              while st and st[-1] != '(' and (prec[st[-1]] > prec[ch] or
                     (prec[st[-1]] == prec[ch] and ch != '^')):
                   out.append(st.pop())
              st.append(ch)
    while st: out.append(st.pop())
    return ''.join(out)

def rev(s):
    st = list(s)
    return ''.join(st.pop() for _ in range(len(st)))

