class CircularQueue:
       def __init__(self, n):
            self.a, self.n, self.front, self.size = [None] * n, n, 0, 0
       def enqueue(self, x):
            if self.size == self.n: return False
            self.a[(self.front + self.size) % self.n] = x
            self.size += 1; return True
       def dequeue(self):
            if self.size == 0: return None
            x = self.a[self.front]
            self.front = (self.front + 1) % self.n
            self.size -= 1; return x

