def group_anagrams(words):
     g = defaultdict(list)
     for w in words: g[''.join(sorted(w))].append(w)
     return list(g.values())

def longest_unique(s):
     last, start, best = {}, 0, 0
     for i, ch in enumerate(s):
         if ch in last and last[ch] >= start:
              start = last[ch] + 1
         last[ch] = i
         best = max(best, i - start + 1)
     return best

class HashTable:
     def __init__(self, m=8):
         self.m, self.n = m, 0
         self.t = [[] for _ in range(m)]
     def _idx(self, k): return hash(k) % self.m
     def put(self, k, v):
         b = self.t[self._idx(k)]
         for i, (kk, _) in enumerate(b):
              if kk == k: b[i] = (k, v); return
         b.append((k, v)); self.n += 1
         if self.n / self.m > 0.75: self._grow()
     def get(self, k):
         for kk, v in self.t[self._idx(k)]:

               if kk == k: return v
           return None
       def _grow(self):
           old = [kv for b in self.t for kv in b]
           self.m *= 2; self.n = 0
           self.t = [[] for _ in range(self.m)]
           for k, v in old: self.put(k, v)

