from collections import deque
def preorder(r):       return [r.val] + preorder(r.left) + preorder(r.right) if r else []
def inorder(r):        return inorder(r.left) + [r.val] + inorder(r.right) if r else []
def postorder(r): return postorder(r.left) + postorder(r.right) + [r.val] if r else []
def level(r):
     out, q = [], deque([r] if r else [])
     while q:
          n = q.popleft(); out.append(n.val)
          if n.left: q.append(n.left)
          if n.right: q.append(n.right)
     return out

 def height(r):

     return -1 if r is None else 1 + max(height(r.left), height(r.right))
# Height of a single node = 0; empty tree = -1

def is_bst(r, lo=float('-inf'), hi=float('inf')):
     if r is None: return True
     if not (lo < r.val < hi): return False
     return is_bst(r.left, lo, r.val) and is_bst(r.right, r.val, hi)

def count_leaves(r):
     if r is None: return 0
     if not r.left and not r.right: return 1
     return count_leaves(r.left) + count_leaves(r.right)

def insert(r, k):
     if r is None: return TreeNode(k)
     if k < r.val: r.left = insert(r.left, k)
     elif k > r.val: r.right = insert(r.right, k)
     return r


def delete(r, k):
     if r is None: return None
     if k < r.val: r.left = delete(r.left, k)
     elif k > r.val: r.right = delete(r.right, k)
     else:
         if not r.left: return r.right
         if not r.right: return r.left
         succ = r.right
         while succ.left: succ = succ.left
         r.val = succ.val
         r.right = delete(r.right, succ.val)
     return r

